before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>
#if defined(__STDC_NO_THREADS__) && __STDC_NO_THREADS__
#error C threads unavailable on this implementation
#endif
#include <threads.h>
static int compute(void *arg) {
    int *result = arg;
    *result = 7;
    return 0;
}
int main(void) {
    int result = 0, status = 0;
    thrd_t worker;
    if (thrd_create(&worker, compute, &result) != thrd_success) return 1;
    if (thrd_join(worker, &status) != thrd_success) abort();
    printf("%d %d\n", result, status);
    return 0;
}
```

